import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

/** Persistent TCP gateway used by Nokia clients; web/admin remain on HTTP. */
final class TcpGameServer implements AutoCloseable {
 static final int MAGIC=GameRelease.WIRE_MAGIC,MAX_BODY=131072,MAX_AUTH_BODY=2048;
 final GunnyServer server;final java.util.Set<Socket> sockets=ConcurrentHashMap.newKeySet();final ServerSocket listener;final int maxClients;final ExecutorService clients=Executors.newCachedThreadPool();final AtomicInteger active=new AtomicInteger();volatile boolean closed;Thread acceptor;
 TcpGameServer(String bind,int port,GunnyServer server,int maxClients)throws IOException {this.server=server;this.maxClients=Math.max(1,maxClients);listener=new ServerSocket();listener.setReuseAddress(true);listener.bind(new InetSocketAddress(bind,port),64);acceptor=new Thread(this::accept,"gunny-tcp-accept");acceptor.start();}
 int port(){return listener.getLocalPort();}
 void accept(){while(!closed)try{Socket socket=listener.accept();if(active.incrementAndGet()>maxClients){active.decrementAndGet();socket.close();continue;}socket.setTcpNoDelay(true);socket.setKeepAlive(true);socket.setSoTimeout(15000);sockets.add(socket);clients.execute(()->serve(socket));}catch(IOException e){if(!closed)System.err.println("TCP accept failed: "+e.getMessage());}}
 void serve(Socket socket){String ip=socket.getInetAddress().getHostAddress();GunnyServer.Session attached=null;try(socket;DataInputStream in=new DataInputStream(new BufferedInputStream(socket.getInputStream()));DataOutputStream out=new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()))){while(!closed){int magic;try{magic=in.readInt();}catch(EOFException end){break;}if(magic!=MAGIC&&magic!=GameRelease.LEGACY_MAGIC&&magic!=GameRelease.HF43_MAGIC)throw new IOException("Bad TCP protocol");int kind=in.readUnsignedByte(),flags=in.readInt();String token=readToken(in);int[] kit={in.readUnsignedByte(),in.readUnsignedByte(),in.readUnsignedByte()};int length=in.readInt();if(length<0||length>MAX_BODY||kind>2||kind==0&&(length!=0||!token.isEmpty())||kind==2&&(length!=16||token.isEmpty())||kind==1&&token.isEmpty()&&length>MAX_AUTH_BODY)throw new IOException("Bad TCP frame");
 if(kind!=0&&!GameRelease.accepts(magic)){
  // Consume the bounded old frame, never dispatch it or read credentials into account objects.
  in.skipNBytes(length);
  if(kind==1)writeReply(out,200,updateReply());else writeReply(out,426,new byte[0]);
  break;
 }
 byte[] body=in.readNBytes(length);if(body.length!=length)throw new EOFException();byte[] response;int status=200;
 if(kind==0){if(!server.limit("hf43-health:"+ip,120)){writeReply(out,429,new byte[0]);break;}response=GunnyServer.capabilities(server.admin.enabled,true).getBytes(java.nio.charset.StandardCharsets.UTF_8);}else if(kind==1){TcpExchange exchange=new TcpExchange(socket,body);headers(exchange.request,flags,kit);if(!token.isEmpty())exchange.request.set("Authorization","Bearer "+token);server.api(exchange);status=exchange.status;response=exchange.output.toByteArray();}else if(kind==2){try{response=server.events.waitFor(token,body);}catch(SecurityException e){status=401;response=new byte[0];}catch(Exception e){status=503;response=new byte[0];}}else{status=400;response=new byte[0];}if(kind==1&&status==200){String activeToken=token;if(token.isEmpty())try{var request=new DataInputStream(new ByteArrayInputStream(body));request.readInt();String action=request.readUTF();if(action.equals("login")){var reply=new DataInputStream(new ByteArrayInputStream(response));if(reply.readUnsignedByte()==0)activeToken=reply.readUTF();}}catch(IOException ignored){}
 var current=server.sessions.get(activeToken);if(current!=null&&current!=attached){if(attached!=null)synchronized(attached){attached.tcpConnections=Math.max(0,attached.tcpConnections-1);}attached=current;synchronized(current){current.tcpSeen=true;current.tcpConnections++;}socket.setSoTimeout(90000);server.events.signal();}}
 if(kind==2&&status==200)socket.setSoTimeout(90000);writeReply(out,status,response);}}catch(Exception e){if(!closed&&!(e instanceof EOFException)&&!(e instanceof SocketTimeoutException))System.err.println("TCP client "+ip+" closed: "+e.getClass().getSimpleName());}finally{if(attached!=null)synchronized(attached){attached.tcpConnections=Math.max(0,attached.tcpConnections-1);server.events.signal();}sockets.remove(socket);active.decrementAndGet();}}
 static String readToken(DataInputStream in)throws IOException {int n=in.readUnsignedShort();if(n==0)return "";if(n!=43)throw new IOException("Invalid token length");byte[] b=new byte[n];in.readFully(b);for(byte value:b){int c=value&255;if(!(c>=65&&c<=90||c>=97&&c<=122||c>=48&&c<=57||c==45||c==95))throw new IOException("Invalid token encoding");}return new String(b,java.nio.charset.StandardCharsets.US_ASCII);}
 static byte[] updateReply()throws IOException {var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeByte(1);out.writeUTF(GameRelease.UPDATE);return bytes.toByteArray();}
 static void writeReply(DataOutputStream out,int status,byte[] response)throws IOException {out.writeInt(status);out.writeInt(response.length);out.write(response);out.flush();}
 static void headers(com.sun.net.httpserver.Headers h,int f,int[] kit){if((f&1073741824)!=0)h.set("X-Gunny-Sulan7912","1");if((f&536870912)!=0)h.set("X-Gunny-Tribal797","1");if((f&268435456)!=0)h.set("X-Gunny-Clock793","1");if((f&134217728)!=0)h.set("X-Gunny-Vip","1");if((f&67108864)!=0)h.set("X-Gunny-Delta","1");if((f&33554432)!=0)h.set("X-Gunny-Tribal","1");if((f&16777216)!=0)h.set("X-Gunny-PlayerUi","1");if((f&8388608)!=0)h.set("X-Gunny-Prefetch","1");if((f&2097152)!=0)h.set("X-Gunny-Chat-Emoji","1");if((f&1048576)!=0)h.set("X-Gunny-Flock","1");if((f&524288)!=0)h.set("X-Gunny-Campaign","1");if((f&65536)!=0)h.set("X-Gunny-Rules","770");if((f&131072)!=0){h.set("X-Gunny-Rules","771");h.set("X-Gunny-Actors","1");h.set("X-Gunny-Live",(f&4194304)!=0?"0":"1");}if((f&262144)!=0){h.set("X-Gunny-Rules","780");h.set("X-Gunny-Expansion","1");}if((f&1)!=0)h.set("X-Gunny-Admin","1");if((f&2)!=0)h.set("X-Gunny-ItemFx","1");if((f&4)!=0)h.set("X-Gunny-Bag","1");if((f&8)!=0)h.set("X-Gunny-Equipment","1");if((f&16)!=0)h.set("X-Gunny-Arsenal","2");if((f&32)!=0)h.set("X-Gunny-Cards","1");if((f&Integer.MIN_VALUE)!=0)h.set("X-Gunny-EmptyKit","1");if((f&64)!=0){h.set("X-Gunny-Items","2");h.set("X-Gunny-Kit",kit[0]+","+kit[1]+","+kit[2]);}if((f&128)!=0)h.set("X-Gunny-RoomFix","1");if((f&256)!=0)h.set("X-Gunny-Wait","1");if((f&512)!=0)h.set("X-Gunny-Match","1");if((f&1024)!=0)h.set("X-Gunny-Social","1");if((f&2048)!=0)h.set("X-Gunny-Chunks","1");if((f&4096)!=0)h.set("X-Gunny-Replay","1");if((f&8192)!=0)h.set("X-Gunny-Client",(f&16384)!=0?"3":"2");if((f&32768)!=0)h.set("X-Gunny-Features","departures");}
 public void close(){closed=true;try{listener.close();}catch(Exception ignored){}for(Socket socket:sockets)try{socket.close();}catch(Exception ignored){}clients.shutdownNow();}
}
